<template><section><div class="page-heading"><div><h1>部门</h1><p>维护单层部门结构。删除部门后，员工会自动变为未分配。</p></div><el-button type="primary" :icon="Plus" @click="visible=true">新建部门</el-button></div><el-table v-loading="loading" :data="departments"><el-table-column prop="name" label="部门名称" min-width="240"/><el-table-column label="员工数" width="120"><template #default="{row}">{{ counts[row.id]||0 }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text type="danger" :icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!departments.length" description="尚未创建部门"/><el-dialog v-model="visible" title="新建部门" width="min(92vw, 460px)" @closed="resetForm"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="部门名称" prop="name"><el-input v-model="form.name" maxlength="100" show-word-limit @keyup.enter="create"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import type{FormInstance,FormRules}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{Delete,Plus}from'@element-plus/icons-vue';import{enterpriseAPI}from'@/api/enterprise';import{validateDepartmentName}from'@/features/enterprise/validation';import type{EnterpriseDepartment,EnterpriseEmployee}from'@/types/enterprise';const departments=ref<EnterpriseDepartment[]>([]),employees=ref<EnterpriseEmployee[]>([]),loading=ref(false),saving=ref(false),visible=ref(false),formRef=ref<FormInstance>(),form=reactive({name:''});const counts=computed(()=>employees.value.reduce<Record<number,number>>((a,e)=>{if(e.department_id)a[e.department_id]=(a[e.department_id]||0)+1;return a},{}));const rules:FormRules={name:[{validator:(_r,_v,cb)=>{const m=validateDepartmentName(form.name);m?cb(new Error(m)):cb()},trigger:'blur'}]};function resetForm(){form.name='';formRef.value?.clearValidate()}async function load(){loading.value=true;try{[departments.value,employees.value]=await Promise.all([enterpriseAPI.listDepartments(),enterpriseAPI.listEmployees()])}finally{loading.value=false}}async function create(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{await enterpriseAPI.createDepartment(form.name);visible.value=false;form.name='';ElMessage.success('部门已创建');await load()}finally{saving.value=false}}async function remove(row:EnterpriseDepartment){await ElMessageBox.confirm(`删除部门“${row.name}”？所属员工将变为未分配。`,'删除部门',{type:'warning'});await enterpriseAPI.deleteDepartment(row.id);ElMessage.success('部门已删除');await load()}onMounted(load);</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p{margin:0;color:#64748b}@media(max-width:640px){.page-heading{flex-direction:column}.page-heading .el-button{width:100%}}</style>
